package com.escapecrystalcalculator;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.Locale;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSeparator;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

final class CalculatorPanel extends PluginPanel
{
    private final JButton start = new JButton("Start");
    private final JButton stop = new JButton("Stop");
    private final JLabel status = new JLabel();
    private final JLabel minimum = valueLabel();
    private final JLabel maximum = valueLabel();
    private final JLabel average = valueLabel();
    private final JLabel recommendation = valueLabel();
    private final JLabel combatSampled = valueLabel();
    private final Supplier<RecordingSession.Snapshot> snapshot;
    private final BooleanSupplier loggedIn;
    private final LongSupplier lastTick;
    private final Timer timer;

    CalculatorPanel(Runnable onStart, Runnable onStop, Supplier<RecordingSession.Snapshot> snapshot,
        BooleanSupplier loggedIn, LongSupplier lastTick)
    {
        this.snapshot = snapshot;
        this.loggedIn = loggedIn;
        this.lastTick = lastTick;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setOpaque(false);
        JLabel title = new JLabel("Escape Crystal Calculator");
        title.setFont(FontManager.getDefaultBoldFont());
        title.setAlignmentX(LEFT_ALIGNMENT);
        content.add(title);
        content.add(Box.createVerticalStrut(12));

        JPanel controls = new JPanel(new GridLayout(1, 2, 5, 0));
        controls.setOpaque(false);
        controls.setAlignmentX(LEFT_ALIGNMENT);
        controls.add(start);
        controls.add(stop);
        content.add(controls);
        content.add(Box.createVerticalStrut(8));
        status.setAlignmentX(LEFT_ALIGNMENT);
        content.add(status);
        content.add(Box.createVerticalStrut(16));

        JPanel statistics = new JPanel(new GridLayout(3, 1, 0, 8));
        statistics.setOpaque(false);
        statistics.setAlignmentX(LEFT_ALIGNMENT);
        statistics.setToolTipText("Input-free gaps during incoming attacks. One game tick is nominally 0.6 seconds.");
        statistics.add(statisticRow("Minimum", minimum));
        statistics.add(statisticRow("Maximum", maximum));
        statistics.add(statisticRow("Average", average));
        content.add(statistics);
        content.add(Box.createVerticalStrut(16));

        JPanel suggestion = new JPanel(new BorderLayout(5, 0));
        suggestion.setOpaque(false);
        suggestion.setAlignmentX(LEFT_ALIGNMENT);
        suggestion.add(new JLabel("Recommended"), BorderLayout.WEST);
        recommendation.setFont(FontManager.getDefaultBoldFont());
        recommendation.setToolTipText("Estimate from combat recorded so far. Longer observed inactivity can raise it.");
        suggestion.add(recommendation, BorderLayout.EAST);
        content.add(suggestion);
        content.add(Box.createVerticalStrut(12));
        JSeparator separator = new JSeparator();
        separator.setAlignmentX(LEFT_ALIGNMENT);
        content.add(separator);
        content.add(Box.createVerticalStrut(10));
        JPanel sampledRow = statisticRow("Combat sampled", combatSampled);
        sampledRow.setAlignmentX(LEFT_ALIGNMENT);
        String sampledTooltip = "<html>Recorded combat time in minutes:seconds, confirmed by incoming hits."
            + "<br>Excludes time between fights and after the last hit."
            + "<br>This measures data collected, not statistical confidence.</html>";
        sampledRow.setToolTipText(sampledTooltip);
        combatSampled.setToolTipText(sampledTooltip);
        content.add(sampledRow);
        add(content, BorderLayout.NORTH);

        start.addActionListener(event -> onStart.run());
        stop.addActionListener(event -> onStop.run());
        timer = new Timer(2000, event -> refresh());
        refresh();
        timer.start();
    }

    void refresh()
    {
        RecordingSession.Snapshot s = snapshot.get();
        start.setEnabled(!s.recording && loggedIn.getAsBoolean());
        start.setToolTipText("Start a new recording, replacing the current results.");
        stop.setEnabled(s.recording);
        long last = lastTick.getAsLong();
        boolean stale = s.recording && s.armed && last != 0 && System.nanoTime() - last > 5_000_000_000L;
        status.setText(wrap(stale ? "Waiting for game updates" : !loggedIn.getAsBoolean()
            && !s.recording && s.gaps == 0 ? "Log in to record" : s.status));
        minimum.setText(s.gaps == 0 ? "—" : duration(s.min));
        maximum.setText(s.gaps == 0 ? "—" : duration(s.max));
        average.setText(s.gaps == 0 ? "—" : duration(s.average));
        recommendation.setText(s.recommendation > 0 ? s.recommendation + " seconds"
            : s.recommendation < 0 ? "> 300 s" : "—");
        long seconds = s.combatTicks * 3 / 5;
        combatSampled.setText(String.format(Locale.ROOT, "%d:%02d", seconds / 60, seconds % 60));
        revalidate();
    }

    static String duration(double ticks)
    {
        return String.format(Locale.ROOT,
            "<html><div align='right'><b>%.1f seconds</b><br>%.1f %s</div></html>",
            ticks * 0.6, ticks, ticks == 1 ? "tick" : "ticks");
    }

    private static JPanel statisticRow(String name, JLabel value)
    {
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setOpaque(false);
        row.add(new JLabel(name), BorderLayout.WEST);
        row.add(value, BorderLayout.EAST);
        return row;
    }

    private static JLabel valueLabel()
    {
        return new JLabel("—", SwingConstants.RIGHT);
    }

    private static String wrap(String text)
    {
        return "<html><body style='width: 150px'>" + text + "</body></html>";
    }

    void dispose()
    {
        timer.stop();
    }
}

package com.escapecrystalcalculator;

import java.util.Arrays;

/** Estimates a recent-attack window from incoming hits; never predicts an attack. */
final class CombatWindow
{
    // Bootstrap only, until two separate incoming updates establish a cadence.
    private static final int INITIAL_QUIET_TICKS = 12;
    private final long[] intervals = new long[7];
    private int size;
    private int next;
    private long lastHit = -1;

    boolean active(long tick)
    {
        return lastHit >= 0 && tick - lastHit <= quietTicks();
    }

    boolean damage(long tick)
    {
        boolean continuing = active(tick);
        if (!continuing)
        {
            size = 0;
            next = 0;
        }
        else if (tick > lastHit)
        {
            intervals[next] = tick - lastHit;
            next = (next + 1) % intervals.length;
            size = Math.min(size + 1, intervals.length);
        }
        lastHit = tick;
        return continuing;
    }

    boolean hasCadence()
    {
        return size > 0;
    }

    long quietTicks()
    {
        if (size == 0)
        {
            return INITIAL_QUIET_TICKS;
        }
        long[] sorted = Arrays.copyOf(intervals, size);
        Arrays.sort(sorted);
        // Allow one missed update/attack; avoid lingering indefinitely after an outlier.
        return Math.max(2, sorted[size / 2] * 2 + 1);
    }

    void reset()
    {
        lastHit = -1;
        size = 0;
        next = 0;
    }
}

package com.escapecrystalcalculator;

import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

final class DamageClassifier
{
    private DamageClassifier()
    {
    }

    static boolean isDamage(Hitsplat hit)
    {
        // Whitelist damage: positive healing/prayer/sanity splats are not damage.
        if (hit.isMine() || hit.isOthers())
        {
            return true;
        }
        switch (hit.getHitsplatType())
        {
            case HitsplatID.POISON:
            case HitsplatID.VENOM:
            case HitsplatID.BLEED:
            case HitsplatID.BURN:
                return true;
            default:
                return false;
        }
    }
}

package com.escapecrystalcalculator;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseManager;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(name = "Escape Crystal Calculator",
    description = "Record combat inactivity to estimate an escape crystal timer",
    tags = {"escape", "crystal", "calculator", "hardcore", "inactivity"})
public class EscapeCrystalCalculatorPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;
    @Inject private MouseManager mouseManager;

    // Each enable owns its UI and measurements. Delayed work can never affect a
    // replacement instance, including a rapid disable/re-enable.
    private volatile SessionState state;
    private final AtomicLong wheelSequence = new AtomicLong();
    private final MouseWheelListener wheelListener = event ->
    {
        wheelSequence.incrementAndGet();
        return event;
    };

    @Override
    protected void startUp()
    {
        SessionState current = new SessionState();
        state = current;
        mouseManager.registerMouseWheelListener(wheelListener);
        clientThread.invokeLater(() ->
        {
            if (state == current)
            {
                publish(current);
            }
        });
        SwingUtilities.invokeLater(() ->
        {
            if (state != current)
            {
                return;
            }
            current.panel = new CalculatorPanel(() -> startRecording(current), () -> stopRecording(current),
                () -> current.latest, () -> current.loggedIn, () -> current.lastGameTickNanos);
            current.navigation = NavigationButton.builder().tooltip("Escape Crystal Calculator")
                .icon(createIcon()).priority(7).panel(current.panel).build();
            toolbar.addNavigation(current.navigation);
        });
    }

    @Override
    protected void shutDown()
    {
        SessionState previous = state;
        state = null;
        mouseManager.unregisterMouseWheelListener(wheelListener);
        if (previous != null)
        {
            SwingUtilities.invokeLater(() ->
            {
                if (previous.panel != null)
                {
                    previous.panel.dispose();
                }
                if (previous.navigation != null)
                {
                    toolbar.removeNavigation(previous.navigation);
                }
            });
        }
    }

    private void startRecording(SessionState current)
    {
        clientThread.invokeLater(() ->
        {
            if (state != current || current.recording.isRecording()
                || client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
            {
                return;
            }
            current.recording = new RecordingSession();
            current.recording.start();
            current.input.reset();
            // Prime counters; clicking Start in the sidebar isn't game input.
            sampleInput(current);
            current.previousLocation = client.getLocalPlayer().getWorldLocation();
            current.lastGameTickNanos = System.nanoTime();
            publish(current);
        });
    }

    private void stopRecording(SessionState current)
    {
        clientThread.invokeLater(() ->
        {
            if (state == current)
            {
                current.recording.stop("Stopped");
                publish(current);
            }
        });
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        SessionState current = state;
        if (current != null && current.recording.isRecording() && client.getGameState() == GameState.LOGGED_IN)
        {
            sampleInput(current);
        }
    }

    private void sampleInput(SessionState current)
    {
        if (current.input.sample(client.getKeyboardIdleTicks(), client.getMouseIdleTicks(),
            client.getMouseLastPressedMillis(), wheelSequence.get()))
        {
            current.recording.input();
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        SessionState current = state;
        if (current != null && current.recording.isRecording() && client.getGameState() == GameState.LOGGED_IN
            && event.getActor() == client.getLocalPlayer() && event.getHitsplat() != null
            && DamageClassifier.isDamage(event.getHitsplat()))
        {
            current.recording.damage();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        SessionState current = state;
        if (current == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        current.lastGameTickNanos = System.nanoTime();
        Player player = client.getLocalPlayer();
        if (player != null)
        {
            WorldPoint location = player.getWorldLocation();
            boolean moving = current.previousLocation != null && !current.previousLocation.equals(location);
            current.recording.tick(moving);
            current.previousLocation = location;
        }
        publish(current);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        SessionState current = state;
        if (current == null)
        {
            return;
        }
        switch (event.getGameState())
        {
            case HOPPING:
                current.recording.stop("Stopped: world hop");
                break;
            case CONNECTION_LOST:
                current.recording.stop("Stopped: connection lost");
                break;
            case LOGIN_SCREEN:
            case LOGGING_IN:
                current.recording.stop("Stopped: logged out");
                break;
            case LOADING:
                current.recording.suspend();
                break;
            default:
                break;
        }
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            current.previousLocation = null;
            current.input.reset();
        }
        publish(current);
    }

    private void publish(SessionState current)
    {
        current.latest = current.recording.snapshot();
        current.loggedIn = client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null;
    }

    static final class SessionState
    {
        // Client-thread-owned state.
        final InputTracker input = new InputTracker();
        RecordingSession recording = new RecordingSession();
        WorldPoint previousLocation;
        // Immutable snapshots / scalars cross to Swing.
        volatile RecordingSession.Snapshot latest = recording.snapshot();
        volatile boolean loggedIn;
        volatile long lastGameTickNanos;
        // Swing-thread-owned UI.
        CalculatorPanel panel;
        NavigationButton navigation;
    }

    static BufferedImage createIcon()
    {
        BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(104, 225, 209));
        g.fillPolygon(new int[]{12, 21, 17, 7, 3}, new int[]{1, 9, 21, 21, 9}, 5);
        g.setColor(new Color(40, 119, 128));
        g.fillPolygon(new int[]{12, 17, 12, 7}, new int[]{3, 10, 21, 10}, 4);
        g.setColor(new Color(211, 255, 246));
        g.drawLine(5, 9, 12, 2);
        g.dispose();
        return image;
    }
}

package com.escapecrystalcalculator;

/** Observes the game's counters, without recording keys or mouse positions. */
final class InputTracker
{
    private int keyboard = -1;
    private int mouse = -1;
    private long lastClick;
    private long wheel;

    boolean sample(int keyboardIdle, int mouseIdle, long clickTime, long wheelSequence)
    {
        boolean initialized = keyboard >= 0;
        boolean input = initialized && (keyboardIdle < keyboard || mouseIdle < mouse
            || keyboardIdle <= 1 || mouseIdle <= 1 || clickTime != lastClick || wheelSequence != wheel);
        keyboard = keyboardIdle;
        mouse = mouseIdle;
        lastClick = clickTime;
        wheel = wheelSequence;
        return input;
    }

    void reset()
    {
        keyboard = -1;
        mouse = -1;
    }
}

package com.escapecrystalcalculator;

import java.util.ArrayList;
import java.util.List;

/** Client-thread-owned combat measurements. Durations are received game ticks. */
final class RecordingSession
{
    private final List<Hit> queuedHits = new ArrayList<>();
    private final CombatWindow combatWindow = new CombatWindow();
    private boolean recording;
    private boolean armed;
    private boolean inCombat;
    private boolean inputSinceTick;
    private boolean deferredDamage;
    private boolean hasExposure;
    private boolean measuredAttackInterval;
    private boolean damageThisTick;
    private long observedCombatTicks;
    private long lastCombatHitTick = -1;
    private long inputEpoch;
    private long tick;
    private long idle;
    private long gapCount;
    private long gapSum;
    private long gapMin = Long.MAX_VALUE;
    private long gapMax;
    private long exposureMax;
    private GapCheckpoint lastDamage;
    private String status = "Ready to record";

    void start()
    {
        recording = true;
        status = "Move the mouse over the game to begin";
    }

    boolean isRecording()
    {
        return recording;
    }

    void input()
    {
        if (!recording)
        {
            return;
        }
        finishGap();
        armed = true;
        inputSinceTick = true;
        inputEpoch++;
        deferredDamage = false;
        status = inCombat ? "Recording combat" : "Waiting for combat";
    }

    void damage()
    {
        if (!recording || !armed)
        {
            return;
        }
        // HitsplatApplied precedes GameTick for this incoming update.
        if (!combatWindow.damage(tick + 1))
        {
            endCombat();
            inCombat = true;
            idle = 0;
            inputSinceTick = true;
        }
        measuredAttackInterval |= combatWindow.hasCadence();
        // Only count time bounded by incoming hits in the same combat period.
        // New hits extend the live measurement; no completed fight is required.
        if (lastCombatHitTick >= 0)
        {
            observedCombatTicks += tick + 1 - lastCombatHitTick;
        }
        lastCombatHitTick = tick + 1;
        damageThisTick = true;
        status = "Recording combat";
        queuedHits.add(new Hit(inputSinceTick ? 0 : idle + 1, inputEpoch));
    }

    void tick(boolean moving)
    {
        if (!recording || !armed)
        {
            return;
        }
        tick++;
        if (!inCombat)
        {
            return;
        }
        if (!combatWindow.active(tick))
        {
            endCombat();
            status = "Waiting for combat";
            return;
        }
        if (!inputSinceTick)
        {
            idle++;
        }
        inputSinceTick = false;
        flushHits(moving);
        if (!moving && deferredDamage)
        {
            // Conservative upper bound for a moving hit activating on stopping.
            exposure(idle);
            deferredDamage = false;
        }
        if (damageThisTick)
        {
            lastDamage = new GapCheckpoint(gapCount, gapSum, gapMin, gapMax, idle);
            damageThisTick = false;
        }
    }

    private void flushHits(boolean moving)
    {
        for (Hit hit : queuedHits)
        {
            if (moving)
            {
                if (hit.epoch == inputEpoch)
                {
                    deferredDamage = true;
                }
            }
            else
            {
                exposure(hit.idle);
            }
        }
        queuedHits.clear();
    }

    private void exposure(long value)
    {
        hasExposure = true;
        exposureMax = Math.max(exposureMax, value);
    }

    private void finishGap()
    {
        if (inCombat && idle > 0)
        {
            gapCount++;
            gapSum += idle;
            gapMin = Math.min(gapMin, idle);
            gapMax = Math.max(gapMax, idle);
        }
        idle = 0;
    }

    private void endCombat()
    {
        lastCombatHitTick = -1;
        // Discard the speculative tail after the last incoming hit. Out-of-combat
        // standing around must not become a completed inactivity sample.
        if (lastDamage != null)
        {
            gapCount = lastDamage.count;
            gapSum = lastDamage.sum;
            gapMin = lastDamage.min;
            gapMax = lastDamage.max;
            idle = lastDamage.idle;
            finishGap();
        }
        idle = 0;
        inCombat = false;
        deferredDamage = false;
        lastDamage = null;
        damageThisTick = false;
    }

    void suspend()
    {
        if (recording && armed)
        {
            finishPendingDamage();
            endCombat();
            combatWindow.reset();
            armed = false;
            inputSinceTick = false;
            status = "Area loaded: move the mouse over the game";
        }
    }

    void stop(String reason)
    {
        if (recording)
        {
            finishPendingDamage();
            endCombat();
            recording = false;
            status = reason;
        }
    }

    private void finishPendingDamage()
    {
        // Treat unknown movement conservatively if stopped between packets.
        flushHits(false);
        if (deferredDamage)
        {
            exposure(idle);
            deferredDamage = false;
        }
        if (damageThisTick)
        {
            lastDamage = new GapCheckpoint(gapCount, gapSum, gapMin, gapMax,
                inputSinceTick ? 0 : idle + 1);
        }
    }

    Snapshot snapshot()
    {
        // Only show hit-confirmed data, so a quiet tail never inflates live stats.
        GapCheckpoint confirmed = inCombat ? lastDamage : null;
        long count = confirmed == null ? gapCount : confirmed.count;
        long sum = confirmed == null ? gapSum : confirmed.sum;
        long min = confirmed == null ? gapMin : confirmed.min;
        long max = confirmed == null ? gapMax : confirmed.max;
        if (confirmed != null && confirmed.idle > 0)
        {
            count++;
            sum += confirmed.idle;
            min = Math.min(min, confirmed.idle);
            max = Math.max(max, confirmed.idle);
        }
        // First whole-second setting whose floored tick threshold exceeds exposure.
        // This accounts for tick resolution, without an adjustable safety factor.
        int recommendation = !hasExposure || !measuredAttackInterval ? 0 : TimerSetting.above(exposureMax);
        return new Snapshot(status, recording, armed, inCombat, count, count == 0 ? 0 : min,
            max, count == 0 ? 0 : (double) sum / count, recommendation, observedCombatTicks);
    }

    private static final class Hit
    {
        private final long idle;
        private final long epoch;

        private Hit(long idle, long epoch)
        {
            this.idle = idle;
            this.epoch = epoch;
        }
    }

    private static final class GapCheckpoint
    {
        private final long count;
        private final long sum;
        private final long min;
        private final long max;
        private final long idle;

        private GapCheckpoint(long count, long sum, long min, long max, long idle)
        {
            this.count = count;
            this.sum = sum;
            this.min = min;
            this.max = max;
            this.idle = idle;
        }
    }

    static final class Snapshot
    {
        final String status;
        final boolean recording;
        final boolean armed;
        final boolean inCombat;
        final long gaps;
        final long min;
        final long max;
        final double average;
        // 0 means insufficient evidence; -1 means no setting within 2–300 seconds.
        final int recommendation;
        final long combatTicks;

        Snapshot(String status, boolean recording, boolean armed, boolean inCombat,
            long gaps, long min, long max, double average, int recommendation, long combatTicks)
        {
            this.status = status;
            this.recording = recording;
            this.armed = armed;
            this.inCombat = inCombat;
            this.gaps = gaps;
            this.min = min;
            this.max = max;
            this.average = average;
            this.recommendation = recommendation;
            this.combatTicks = combatTicks;
        }
    }
}

package com.escapecrystalcalculator;

final class TimerSetting
{
    private TimerSetting()
    {
    }

    // First whole-second setting whose floored tick threshold exceeds exposure.
    // -1 means no allowed setting (2–300 seconds) is high enough.
    static int above(long ticks)
    {
        return ticks >= 500 ? -1 : (int) Math.max(2, ((ticks + 1) * 3 + 4) / 5);
    }
}

package com.escapecrystalcalculator;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class EscapeCrystalCalculatorLauncher
{
